private data class Palette(val bg: Color, val card: Color, val text: Color, val muted: Color, val green: Color, val gold: Color, val red: Color, val elevated: Color)
private val PLight = Palette(Color(0xFFF2F7F4), Color.White, Color(0xFF08241C), Color(0xFF71847C), Color(0xFF16C98A), Color(0xFFFFC857), Color(0xFFE65353), Color(0xFFE8F2ED))
private val PDark = Palette(Color(0xFF061512), Color(0xFF0D211C), Color(0xFFF2FBF7), Color(0xFF9AB3A9), Color(0xFF24D995), Color(0xFFFFC857), Color(0xFFFF6B6B), Color(0xFF163129))

@Composable
fun YurdunuBilMainV3() {
    val context = LocalContext.current
    val prefs = remember { context.getSharedPreferences("yurdunu_bil_native", 0) }
    var dark by remember { mutableStateOf(prefs.getBoolean("dark_theme", false)) }
    val p = if (dark) PDark else PLight
    var tab by rememberSaveable { mutableIntStateOf(0) }
    var topic by remember { mutableStateOf<Topic?>(null) }
    var city by remember { mutableStateOf<Province?>(null) }
    var questions by remember { mutableStateOf<List<Question>?>(null) }
    var quizTitle by remember { mutableStateOf("") }
    var arenaFocus by remember { mutableStateOf(false) }

    fun startQuiz(title: String, mode: SharedGameMode) { val picked = SharedQuestionPool.pick(mode); if (picked.isNotEmpty()) { quizTitle = title; questions = picked; prefs.edit().putString("last_activity", title).apply() } }
    BackHandler(enabled = topic != null || city != null || questions != null || tab != 0) { when { questions != null -> questions = null; topic != null -> topic = null; city != null -> city = null; else -> tab = 0 } }

    if (topic != null) { val selected = topic!!; LessonV3(selected, p, prefs, { topic = null }) { topic = null; startQuiz(selected.title, SharedGameMode("topic-${selected.title}", selected.title, selected.subtitle, selected.icon, 10, 180, 100, SharedQuestionPool.topicForLibrary(selected.title))) }; return }
    if (city != null) { ProvinceV3(city!!, p) { city = null }; return }
    if (questions != null) { QuizV3(quizTitle, questions!!, p, prefs) { questions = null }; return }

    MaterialTheme(colorScheme = if (dark) darkColorScheme(primary = p.green, background = p.bg, surface = p.card, onSurface = p.text) else lightColorScheme(primary = p.green, background = p.bg, surface = p.card, onSurface = p.text)) {
        Scaffold(containerColor = p.bg, bottomBar = {
            NavigationBar(containerColor = p.card, tonalElevation = 8.dp) {
                val items = listOf("Ana Sayfa" to Icons.Default.Home, "Kütüphane" to Icons.Default.MenuBook, "Etkinlikler" to Icons.Default.SportsEsports, "Ayarlar" to Icons.Default.Settings)
                items.forEachIndexed { i, pair -> NavigationBarItem(selected = tab == i, onClick = { tab = i }, icon = { Icon(pair.second, pair.first) }, label = { Text(pair.first, fontSize = 10.sp) }, colors = NavigationBarItemDefaults.colors(selectedIconColor = p.text, selectedTextColor = p.text, indicatorColor = p.green.copy(alpha = .18f), unselectedIconColor = p.muted, unselectedTextColor = p.muted)) }
            }
        }) { pad ->
            when (tab) {
                0 -> HomeV3(p, prefs, { startQuiz("Hızlı 10", SharedGameModes.quick) }) { arenaFocus = true; tab = 2 }
                1 -> LibraryV3(p, { topic = it }, { city = it })
                2 -> EventsV3(p, arenaFocus) { startQuiz(it.title, it) }
                else -> SettingsV3(p, prefs, dark) { dark = it; prefs.edit().putBoolean("dark_theme", it).apply() }
            }
        }
    }
}

@Composable private fun HomeV3(p: Palette, prefs: SharedPreferences, quick: () -> Unit, arena: () -> Unit) {
    val list = rememberLazyListState(); val solved = prefs.getInt("solved", 0); val correct = prefs.getInt("correct", 0); val xp = prefs.getInt("xp", 0); val accuracy = if (solved == 0) 0 else (correct * 100f / solved).roundToInt()
    LazyColumn(state = list, contentPadding = PaddingValues(bottom = 24.dp), verticalArrangement = Arrangement.spacedBy(13.dp)) {
        item { Box(Modifier.fillMaxWidth().background(Brush.linearGradient(listOf(Color(0xFF06241C), Color(0xFF0B6048))), RoundedCornerShape(bottomStart = 32.dp, bottomEnd = 32.dp)).statusBarsPadding().padding(22.dp)) { Column { Row(verticalAlignment = Alignment.CenterVertically) { Column(Modifier.weight(1f)) { Text("Yurdunu Bil", color = Color.White, fontSize = 29.sp, fontWeight = FontWeight.Black); Text("KPSS Önlisans • Türkiye Coğrafyası", color = Color(0xFFC9F8E1), fontSize = 11.sp) }; Text("Lv.${1 + xp / 500}", color = Color.White, fontWeight = FontWeight.Black) }; Spacer(Modifier.height(18.dp)); Text("Bugün Türkiye'yi biraz daha çöz. ✨", color = Color.White, fontSize = 21.sp, fontWeight = FontWeight.ExtraBold); Spacer(Modifier.height(13.dp)); Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) { HeaderStatV3("$solved", "SORU"); HeaderStatV3("$xp", "XP"); HeaderStatV3("${prefs.getInt("streak", 0)}", "SERİ") } } } }
        item { CardV3(p) { Row(verticalAlignment = Alignment.CenterVertically) { Text("🎯", fontSize = 34.sp); Spacer(Modifier.width(12.dp)); Column(Modifier.weight(1f)) { EyebrowV3("BUGÜNÜN GÖREVİ", p.green); Text("Hızlı 10", color = p.text, fontSize = 20.sp, fontWeight = FontWeight.Black); Text("Kısa bir coğrafya turuyla ritmini koru.", color = p.muted, fontSize = 12.sp) } }; Spacer(Modifier.height(12.dp)); Button(onClick = quick, modifier = Modifier.fillMaxWidth().height(50.dp), shape = RoundedCornerShape(16.dp), colors = ButtonDefaults.buttonColors(containerColor = p.green, contentColor = Color(0xFF052219))) { Text("Başla • 10 Soru", fontWeight = FontWeight.Black) } } }
        item { Row(Modifier.padding(horizontal = 16.dp), horizontalArrangement = Arrangement.spacedBy(10.dp)) { MiniV3(p, "⚡", "Hızlı 10", "10 soru", quick, Modifier.weight(1f)); MiniV3(p, "🔥", "Bilgi Zinciri", "Serini büyüt", quick, Modifier.weight(1f)) } }
        item { CardV3(p, dark = true) { Row(verticalAlignment = Alignment.CenterVertically) { Text("⚔️", fontSize = 34.sp); Spacer(Modifier.width(12.dp)); Column(Modifier.weight(1f)) { EyebrowV3("ARENA", p.gold); Text("Bilgini sahaya çıkar.", color = Color.White, fontSize = 20.sp, fontWeight = FontWeight.Black); Text("1v1 • hız • bölge • Türkiye Ustası", color = Color.White.copy(alpha = .7f), fontSize = 12.sp) } }; Spacer(Modifier.height(12.dp)); Button(onClick = arena, modifier = Modifier.fillMaxWidth().height(50.dp), shape = RoundedCornerShape(16.dp), colors = ButtonDefaults.buttonColors(containerColor = p.gold, contentColor = Color(0xFF142117))) { Text("Arena'ya Git", fontWeight = FontWeight.Black) } } }
        item { CardV3(p) { EyebrowV3("GELİŞİMİN", p.green); Text("%$accuracy genel doğruluk", color = p.text, fontSize = 21.sp, fontWeight = FontWeight.Black); Text(if (solved == 0) "İlk testini çöz ve ilerlemeni başlat." else "$correct doğru cevapla devam ediyorsun.", color = p.muted, fontSize = 12.sp); Spacer(Modifier.height(10.dp)); LinearProgressIndicator(progress = { accuracy / 100f }, modifier = Modifier.fillMaxWidth().height(8.dp).clip(RoundedCornerShape(8.dp)), color = p.green, trackColor = p.elevated) } }
        item { CardV3(p) { EyebrowV3("DEVAM ET", p.gold); Text(prefs.getString("last_activity", "Henüz çalışma yok") ?: "Henüz çalışma yok", color = p.text, fontSize = 17.sp, fontWeight = FontWeight.Black); Text("Son çalışmana kaldığın yerden devam et.", color = p.muted, fontSize = 12.sp) } }
    }
}

@Composable private fun HeaderStatV3(v: String, l: String) { Column(Modifier.clip(RoundedCornerShape(13.dp)).background(Color.White.copy(alpha = .09f)).padding(horizontal = 12.dp, vertical = 8.dp)) { Text(v, color = Color.White, fontWeight = FontWeight.Black); Text(l, color = Color.White.copy(alpha = .58f), fontSize = 7.sp) } }
@Composable private fun EyebrowV3(t: String, c: Color) { Text(t, color = c, fontSize = 10.sp, fontWeight = FontWeight.Black, letterSpacing = 1.sp) }
@Composable private fun CardV3(p: Palette, mod: Modifier = Modifier, dark: Boolean = false, content: @Composable ColumnScope.() -> Unit) { Card(modifier = mod.fillMaxWidth().padding(horizontal = 16.dp), shape = RoundedCornerShape(22.dp), elevation = CardDefaults.cardElevation(defaultElevation = 3.dp), colors = CardDefaults.cardColors(containerColor = if (dark) Color.Transparent else p.card)) { Column(if (dark) Modifier.background(Brush.linearGradient(listOf(Color(0xFF05251D), Color(0xFF0B4B3A))).then(Modifier.padding(17.dp))) else Modifier.padding(17.dp), content = content) } }
@Composable private fun MiniV3(p: Palette, icon: String, title: String, sub: String, click: () -> Unit, mod: Modifier) { CardV3(p, mod.clickable(onClick = click)) { Text(icon, fontSize = 28.sp); Spacer(Modifier.height(6.dp)); Text(title, color = p.text, fontWeight = FontWeight.Black); Text(sub, color = p.green, fontSize = 10.sp, fontWeight = FontWeight.Bold) } }

@Composable private fun LibraryV3(p: Palette, onTopic: (Topic) -> Unit, onCity: (Province) -> Unit) { var search by rememberSaveable { mutableStateOf("") }; val list = rememberLazyListState(); val topics = GeographyData.topics.filter { it.title.contains(search, true) || it.subtitle.contains(search, true) }; LazyColumn(state = list, contentPadding = PaddingValues(top = 12.dp, bottom = 28.dp), verticalArrangement = Arrangement.spacedBy(11.dp)) { item { Column(Modifier.padding(horizontal = 16.dp)) { Text("Kütüphane", color = p.text, fontSize = 29.sp, fontWeight = FontWeight.Black); Text("Önce oku → anla → sonra test et.", color = p.green, fontSize = 12.sp, fontWeight = FontWeight.Bold); Spacer(Modifier.height(8.dp)); OutlinedTextField(value = search, onValueChange = { search = it }, modifier = Modifier.fillMaxWidth(), singleLine = true, shape = RoundedCornerShape(17.dp), label = { Text("Konu ara") }, leadingIcon = { Icon(Icons.Default.Search, null) }, colors = OutlinedTextFieldDefaults.colors(focusedBorderColor = p.green, unfocusedBorderColor = p.elevated, focusedLabelColor = p.green, cursorColor = p.green, focusedTextColor = p.text, unfocusedTextColor = p.text)) } }; item { CardV3(p, dark = true) { EyebrowV3("ÇALIŞMA KÜTÜPHANESİ", p.green); Text("12 ana konu • derinlemesine çalışma", color = Color.White, fontSize = 20.sp, fontWeight = FontWeight.Black); Text("Dolu dolu anlatım, kavramlar, sınav tuzakları ve kendini yoklama bölümü.", color = Color.White.copy(alpha = .72f), fontSize = 12.sp, lineHeight = 18.sp) } }; item { Text("Konu Bankası", color = p.text, fontSize = 19.sp, fontWeight = FontWeight.Black, modifier = Modifier.padding(horizontal = 16.dp)) }; items(topics, key = { it.title }) { t -> CardV3(p, Modifier.clickable { onTopic(t) }) { Row(verticalAlignment = Alignment.CenterVertically) { Surface(shape = RoundedCornerShape(15.dp), color = p.elevated) { Text(t.icon, fontSize = 27.sp, modifier = Modifier.padding(10.dp)) }; Spacer(Modifier.width(12.dp)); Column(Modifier.weight(1f)) { Text(t.title, color = p.text, fontWeight = FontWeight.Black, fontSize = 16.sp); Text(t.subtitle, color = p.muted, fontSize = 11.sp, maxLines = 2, overflow = TextOverflow.Ellipsis); Text("Ders sayfasını aç →", color = p.green, fontSize = 10.sp, fontWeight = FontWeight.Bold) }; Icon(Icons.Default.ChevronRight, null, tint = p.green) } } }; item { Text("İl Keşfi", color = p.text, fontSize = 19.sp, fontWeight = FontWeight.Black, modifier = Modifier.padding(horizontal = 16.dp)); Text("İl → bölge → özellik bağlantısını kur.", color = p.muted, fontSize = 11.sp, modifier = Modifier.padding(horizontal = 16.dp)) }; items(GeographyData.provinces, key = { it.name }) { c -> CardV3(p, Modifier.clickable { onCity(c) }) { Row(verticalAlignment = Alignment.CenterVertically) { Text("📍", fontSize = 23.sp); Spacer(Modifier.width(10.dp)); Column(Modifier.weight(1f)) { Text(c.name, color = p.text, fontWeight = FontWeight.Black); Text(c.region, color = p.green, fontSize = 10.sp, fontWeight = FontWeight.Bold); Text(c.clue, color = p.muted, fontSize = 10.sp, maxLines = 2, overflow = TextOverflow.Ellipsis) }; Icon(Icons.Default.ChevronRight, null, tint = p.green) } } } } }

