ifier.height(7.dp)); Text("${i + 1}. $q", color = p.text, fontSize = 13.sp, lineHeight = 19.sp) } }; Spacer(Modifier.height(12.dp)); Button(onClick = test, modifier = Modifier.fillMaxWidth().height(50.dp), shape = RoundedCornerShape(16.dp), colors = ButtonDefaults.buttonColors(containerColor = p.green, contentColor = Color(0xFF052219))) { Text("Şimdi Konuyu Test Et", fontWeight = FontWeight.Black) }; Spacer(Modifier.height(22.dp)) } } }

