@Composable private fun SettingsV3(p: Palette, prefs: SharedPreferences, dark: Boolean, setDark: (Boolean) -> Unit) { val context = LocalContext.current; val activity = context as? Activity; var enabled by remember { mutableStateOf(prefs.getBoolean("notifications_enabled", false)) }; LazyColumn(contentPadding = PaddingValues(16.dp, 10.dp, 16.dp, 28.dp), verticalArrangement = Arrangement.spacedBy(11.dp)) { item { Text("Ayarlar", color = p.text, fontSize = 29.sp, fontWeight = FontWeight.Black); Text("Tema, bildirim ve ilerleme.", color = p.muted, fontSize = 12.sp) }; item { CardV3(p) { Row(verticalAlignment = Alignment.CenterVertically) { Text("🌙", fontSize = 23.sp); Spacer(Modifier.width(10.dp)); Column(Modifier.weight(1f)) { Text("Karanlık tema", color = p.text, fontWeight = FontWeight.Black); Text("Göz yormayan koyu arayüz", color = p.muted, fontSize = 10.sp) }; Switch(checked = dark, onCheckedChange = setDark, colors = SwitchDefaults.colors(checkedThumbColor = p.green, checkedTrackColor = p.green.copy(alpha = .28f))) } } }; item { CardV3(p) { Row(verticalAlignment = Alignment.CenterVertically) { Text("🔔", fontSize = 23.sp); Spacer(Modifier.width(10.dp)); Column(Modifier.weight(1f)) { Text("Bildirimler", color = p.text, fontWeight = FontWeight.Black); Text("Her gün 20:00 hatırlatma", color = p.muted, fontSize = 10.sp) }; Switch(checked = enabled, onCheckedChange = { v -> if (v && android.os.Build.VERSION.SDK_INT >= 33 && activity?.checkSelfPermission("android.permission.POST_NOTIFICATIONS") != PackageManager.PERMISSION_GRANTED) activity?.requestPermissions(arrayOf("android.permission.POST_NOTIFICATIONS"), 9001); enabled = v; prefs.edit().putBoolean("notifications_enabled", v).apply(); if (v) NotificationHelper.scheduleDaily(context) else NotificationHelper.cancelDaily(context) }, colors = SwitchDefaults.colors(checkedThumbColor = p.green, checkedTrackColor = p.green.copy(alpha = .28f))) }; Spacer(Modifier.height(9.dp)); OutlinedButton(onClick = { if (NotificationHelper.canNotify(context)) NotificationHelper.sendTest(context) else if (android.os.Build.VERSION.SDK_INT >= 33) activity?.requestPermissions(arrayOf("android.permission.POST_NOTIFICATIONS"), 9001) }, modifier = Modifier.fillMaxWidth(), shape = RoundedCornerShape(15.dp), colors = ButtonDefaults.outlinedButtonColors(contentColor = p.green)) { Icon(Icons.Default.NotificationsActive, null); Spacer(Modifier.width(7.dp)); Text("Test bildirimi gönder", fontWeight = FontWeight.Bold) } } }; item { CardV3(p) { EyebrowV3("İLERLEME", p.green); Text("Çözülen soru: ${prefs.getInt("solved", 0)}", color = p.text); Text("XP: ${prefs.getInt("xp", 0)}", color = p.text); Text("Doğru: ${prefs.getInt("correct", 0)}", color = p.muted); Text("Yanlış: ${prefs.getInt("wrong", 0)}", color = p.muted) } }; item { CardV3(p) { EyebrowV3("UYGULAMA", p.gold); Text("Yurdunu Bil • 0.3.0", color = p.text, fontWeight = FontWeight.Black); Text("Stabil geri dönüş • kalıcı giriş • derin kütüphane • tema • bildirim", color = p.muted, fontSize = 11.sp) } } } }

@Composable private fun QuizV3(title: String, qs: List<Question>, p: Palette, prefs: SharedPreferences, done: () -> Unit) { var index by rememberSaveable(title) { mutableIntStateOf(0) }; var selected by rememberSaveable(title) { mutableIntStateOf(-1) }; var correct by rememberSaveable(title) { mutableIntStateOf(0) }; var wrong by rememberSaveable(title) { mutableIntStateOf(0) }; var finished by rememberSaveable(title) { mutableStateOf(false) }; val q = qs.getOrNull(index); Column(Modifier.fillMaxSize().background(p.bg).statusBarsPadding().navigationBarsPadding().padding(16.dp)) { if (finished || q == null) { CardV3(p, Modifier.padding(horizontal = 0.dp), true) { EyebrowV3("TEST TAMAMLANDI 🎉", p.green); Text(title, color = Color.White, fontSize = 23.sp, fontWeight = FontWeight.Black); Spacer(Modifier.height(10.dp)); Text("$correct doğru • $wrong yanlış", color = Color.White, fontSize = 18.sp, fontWeight = FontWeight.Black); Text("%${if (qs.isEmpty()) 0 else (correct * 100f / qs.size).roundToInt()} başarı", color = Color.White.copy(alpha = .72f)); Spacer(Modifier.height(14.dp)); Button(onClick = done, modifier = Modifier.fillMaxWidth().height(50.dp), shape = RoundedCornerShape(16.dp), colors = ButtonDefaults.buttonColors(containerColor = p.green, contentColor = Color(0xFF052219))) { Text("Devam Et", fontWeight = FontWeight.Black) } }; return }; Row(verticalAlignment = Alignment.CenterVertically) { IconButton(onClick = done) { Icon(Icons.Default.ArrowBack, "Çık", tint = p.text) }; Column(Modifier.weight(1f)) { EyebrowV3(title, p.green); Text("Soru ${index + 1} / ${qs.size}", color = p.text, fontWeight = FontWeight.Black) } }; LinearProgressIndicator(progress = { (index + 1f) / qs.size }, modifier = Modifier.fillMaxWidth().height(7.dp), color = p.green, trackColor = p.elevated); Spacer(Modifier.height(12.dp)); CardV3(p, Modifier.padding(horizontal = 0.dp)) { Text(q.text, color = p.text, fontSize = 17.sp, lineHeight = 24.sp, fontWeight = FontWeight.Bold) }; Spacer(Modifier.height(10.dp)); q.options.forEachIndexed { i, option -> val right = i == q.correctIndex; val bg = when { selected == -1 -> p.card; selected == i && right -> p.green.copy(alpha = .18f); selected == i && !right -> p.red.copy(alpha = .16f); selected != -1 && right -> p.green.copy(alpha = .12f); else -> p.card }; Card(modifier = Modifier.fillMaxWidth().padding(bottom = 8.dp).clickable(enabled = selected == -1) { selected = i; if (right) correct++ else wrong++ }, shape = RoundedCornerShape(17.dp), colors = CardDefaults.cardColors(containerColor = bg)) { Row(Modifier.padding(14.dp), verticalAlignment = Alignment.Top) { Text("${('A'.code + i).toChar()}", color = p.green, fontWeight = FontWeight.Black); Spacer(Modifier.width(10.dp)); Text(option, color = p.text, fontSize = 13.sp, lineHeight = 19.sp, modifier = Modifier.weight(1f)) } } }; if (selected != -1) { CardV3(p, Modifier.padding(horizontal = 0.dp)) { EyebrowV3(if (selected == q.correctIndex) "DOĞRU" else "YANLIŞ", if (selected == q.correctIndex) p.green else p.red); Text(q.explanation, color = p.text, fontSize = 12.sp, lineHeight = 18.sp); Spacer(Modifier.height(8.dp)); Button(onClick = { if (index + 1 == qs.size) { prefs.edit().putInt("solved", prefs.getInt("solved", 0) + qs.size).putInt("correct", prefs.getInt("correct", 0) + correct).putInt("wrong", prefs.getInt("wrong", 0) + wrong).putInt("xp", prefs.getInt("xp", 0) + correct * 10).apply(); finished = true } else { index++; selected = -1 } }, modifier = Modifier.fillMaxWidth().height(48.dp), shape = RoundedCornerShape(16.dp), colors = ButtonDefaults.buttonColors(containerColor = p.green, contentColor = Color(0xFF052219))) { Text(if (index + 1 == qs.size) "Sonucu Gör" else "Sonraki Soru", fontWeight = FontWeight.Black) } } } } }
